  /* 基础: 切角矩形 60x60x2 (局部 Y∈[-1,1])
     (a) HD NOTCH: 左上角 4x4 真镂空 (Shape holes)
     (d) Shutter 开口槽: 前缘磁头通道贯穿孔 (与下壳/快门共用 HEAD_CHANNEL) */
  const shape = chamferRectShape([
    { type: 'rect', x0: -28, z0: -28, x1: -24, z1: -24 },
    { type: 'rect', x0: HEAD_CHANNEL.x, z0: HEAD_CHANNEL.z,
      x1: HEAD_CHANNEL.x + HEAD_CHANNEL.w, z1: HEAD_CHANNEL.z + HEAD_CHANNEL.h },
  ]);
  group.add(createEdgedMesh(extrudeShell(shape, 2), fill));

  /* (b) 标签凹槽: 上半部分中央 36x22 薄盒, 略低于上表面 (局部上表面 y=1) */
  group.add(createEdgedBox(36, 0.4, 22, 0, 0.6, -15, fill));
  /* (c) 内部凹槽: 标签凹槽下方 20x10 (金属滑盖滑动凹陷区) */
  group.add(createEdgedBox(20, 0.4, 10, 0, 0.6, 2, fill));

  /* (e) 箭头标记: Shutter 开口附近的小三角箭头, 指向磁头通道 (+Z) */
  const arrowMat = lineMat(BLUE);
  const tri = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    v3(-9.5, 1.03, 13.8), v3(-7, 1.03, 12), v3(-4.5, 1.03, 13.8), v3(-9.5, 1.03, 13.8),
  ]), arrowMat);
  const tail = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    v3(-7, 1.03, 12), v3(-7, 1.03, 10.5),
  ]), arrowMat);
  tri.renderOrder = 10; tail.renderOrder = 10;
  group.add(tri, tail);

  return { group, fillMats: [fill] };
}

/* ================= 3.2 / 3.5 DUST LINER (防尘布, C 字形圆环) ================= */
function createDustLiner() {
  const group = new THREE.Group();
  const fill = ghostFill();

  /* C 字形: 外圆 r=24, 内圆 r=20, 前缘切出矩形缺口 (与磁头通道对位, X∈[-10,-4])
     单条外轮廓路径: 外弧(长程) + 缺口两侧 + 内弧(长程) */
  const OUTER = 24, INNER = 20;
  const OL = v2(-10, Math.sqrt(OUTER * OUTER - 100));   // 外圆 x=-10: z=21.82
  const IL = v2(-10, Math.sqrt(INNER * INNER - 100));   // 内圆 x=-10: z=17.32
  const IR = v2(-4,  Math.sqrt(INNER * INNER - 16));    // 内圆 x=-4 : z=19.60
  const OR = v2(-4,  Math.sqrt(OUTER * OUTER - 16));    // 外圆 x=-4 : z=23.66
  const s = new THREE.Shape();
  s.moveTo(OL.x, OL.y);
  s.lineTo(IL.x, IL.y);
  s.absarc(0, 0, INNER, Math.atan2(IL.y, IL.x), Math.atan2(IR.y, IR.x), false); // 内弧长程(经背面)
  s.lineTo(OR.x, OR.y);
  s.absarc(0, 0, OUTER, Math.atan2(OR.y, OR.x), Math.atan2(OL.y, OL.x), true);  // 外弧长程(经背面)
  s.closePath();

  const geo = extrudeShell(s, 0.3); // 极薄挤压
  group.add(createEdgedMesh(geo, fill));

  return { group, fillMats: [fill] };
}

/* ================= 3.3 MAGNETIC DISK (磁片, 唯一实体填充部件) ================= */
function createMagneticDisk() {
  const group = new THREE.Group();
  const mat = ghostFill(DISK_BLUE); // 爆炸态目标 opacity 0.5

  const geo = new THREE.CylinderGeometry(22, 22, 0.3, 64);
  group.add(createEdgedMesh(geo, mat, 15, DISK_EDGE_MAT)); // 深蓝描边

  /* 表面数据轨道反光: 三条短斜线 (弧线近似) */
  const trackMat = lineMat(TRACK_BLUE);
  const arcs = [[14, 3.4, 4.0], [17, 3.7, 4.3], [20, 4.0, 4.6]];
  for (const [r, a0, a1] of arcs) {
    const pts = [];
    for (let i = 0; i <= 8; i++) {
      const a = lerp(a0, a1, i / 8);
      pts.push(v3(r * Math.cos(a), 0.16, r * Math.sin(a))); // 略高于上表面
    }
    const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), trackMat);
    line.renderOrder = 10;
    group.add(line);
  }
  return { group, fillMats: [mat] };
}

/* ================= 3.4 HUB (中心金属盘) ================= */
function createHub() {
  const group = new THREE.Group();
  const mat = ghostFill(DISK_BLUE);

  /* 圆盘 r=5 厚 0.4, 中央圆形孔 + 旁边方形孔 (驱动主轴卡口) */
  const shape = new THREE.Shape();
  shape.absarc(0, 0, 5, 0, Math.PI * 2, false);
  const holeC = new THREE.Path();
  holeC.absarc(0, 0, 1, 0, Math.PI * 2, true);
  shape.holes.push(holeC);
  const holeS = new THREE.Path();
  holeS.moveTo(1.2, -0.8); holeS.lineTo(2.8, -0.8); holeS.lineTo(2.8, 0.8); holeS.lineTo(1.2, 0.8);
  holeS.closePath();
  shape.holes.push(holeS);

  const geo = extrudeShell(shape, 0.4);
  group.add(createEdgedMesh(geo, mat, 15, DISK_EDGE_MAT));
  return { group, fillMats: [mat] };
}

/* ================= 3.6 BOTTOM SHELL (下壳) ================= */
function createBottomShell() {
  const group = new THREE.Group();
  const fill = ghostFill();

  /* 基础: 切角矩形 + 孔洞
     (b) 中央圆孔 r=7 (主轴孔)
     (g) 磁头通道贯穿孔 (与上壳/快门共用 HEAD_CHANNEL)
     (f) WRITE PROTECT NOTCH: 右后角 3x3 方形镂空 */
  const shape = chamferRectShape([
    { type: 'circle', x: 0, z: 0, r: 7 },
    { type: 'rect', x0: HEAD_CHANNEL.x, z0: HEAD_CHANNEL.z,
      x1: HEAD_CHANNEL.x + HEAD_CHANNEL.w, z1: HEAD_CHANNEL.z + HEAD_CHANNEL.h },
    { type: 'rect', x0: 25, z0: -28, x1: 28, z1: -25 },
  ]);
  group.add(createEdgedMesh(extrudeShell(shape, 2), fill));

  /* (a) 中央大圆形凹陷: 直径 44 薄圆柱叠加在上表面 (磁片容纳区) */
  group.add(createEdgedCylinder(22, 22, 0.3, 0, 0.75, 0, fill, 48));
  /* (c) 四角定位柱 */
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    group.add(createEdgedCylinder(1.5, 1.5, 1, 22 * sx, 1.5, 22 * sz, fill, 24));
  }
  /* (d) LIFTER: 中下方小矩形凸起 8x4x1 */
  group.add(createEdgedBox(8, 1, 4, 0, 1.5, 8, fill));
  /* (e) SHUTTER SPRING 区: 前边缘中部小矩形凹槽 (前立面内嵌) */
  group.add(createEdgedBox(10, 4, 0.3, 0, 0, 29.6, fill));

  return { group, fillMats: [fill] };
}

/* ================= 3.7 SHUTTER (金属滑盖, 不透明, 唯一开孔部件) ================= */
function createShutter() {
  const group = new THREE.Group();
  /* 不透明金属材质 — 禁止半透明 (自检 #1) */
  const metal = new THREE.MeshBasicMaterial({ color: SHUTTER_GRAY });

  /* 板面 22(X) x 16(Z) x 1(Y), 局部 Y∈[0,1] (组原点在板面下表面)
     矩形真镂空窗口: 偏左 X∈[-10,-4] (自检 #2)
     - 窗口短边(6, 沿X) ∥ 快门长边(22, 沿X)
     - 窗口长边(14, 沿Z) ∥ 快门短边(16, 沿Z)  => 开孔长轴 ⟂ 快门长轴
     局部坐标由 HEAD_CHANNEL 推导, 与上下壳三处一致 (自检 #3) */
  const winX0 = HEAD_CHANNEL.x;
  const winX1 = HEAD_CHANNEL.x + HEAD_CHANNEL.w;            // -10 .. -4
  const winZ0 = HEAD_CHANNEL.z - 22;                        // 组中心 z=22 -> 窗口世界 [15,29]
  const winZ1 = HEAD_CHANNEL.z + HEAD_CHANNEL.h - 22;       // -7 .. 7

  const plateShape = new THREE.Shape();
  plateShape.moveTo(-11, -8); plateShape.lineTo(11, -8); plateShape.lineTo(11, 8); plateShape.lineTo(-11, 8);
  plateShape.closePath();
  const win = new THREE.Path();
  win.moveTo(winX0, winZ0); win.lineTo(winX1, winZ0); win.lineTo(winX1, winZ1); win.lineTo(winX0, winZ1);
  win.closePath();
  plateShape.holes.push(win);

  const plateGeo = new THREE.ExtrudeGeometry(plateShape, { depth: 1, bevelEnabled: false });
  plateGeo.rotateX(-Math.PI / 2); // 局部 Y∈[0,1]
  group.add(createEdgedMesh(plateGeo, metal));

  /* U 形包边: 前立面竖条 + 底部折边 (随组整体移动, 同材质) */
  group.add(createEdgedBox(22, 1, 1, 0, -0.5, 8, metal));   // 前缘立条 (世界 z=30 处)
  group.add(createEdgedBox(22, 1, 7, 0, -1.5, 4, metal));   // 底部折边

  return { group, fillMats: [] }; // 无透明度动画
}

/* ================= WRITE PROTECT TAB (防写滑块) ================= */
function createWriteProtectTab() {
  const group = new THREE.Group();
  const fill = ghostFill(); // 爆炸态目标 0.5
  group.add(createEdgedBox(3, 2, 3, 0, 0, 0, fill));
  return { group, fillMats: [fill] };
}

