/* ================= 连接虚线 (LineDashedMaterial) ================= */
const dashedMat = new THREE.LineDashedMaterial({
  color: BLUE, dashSize: 3, gapSize: 2.5,
  transparent: true, opacity: 0, depthWrite: false,
});
const dashedLines = [];

function makeDashed(a, b) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), dashedMat);
  line.computeLineDistances(); // LineDashedMaterial 必须
  line.renderOrder = 11;
  line.visible = false;
  scene.add(line);
  dashedLines.push(line);
}
function setupDashedLines() {
  /* 4 条垂直虚线: 贯穿四个切角, Top Shell -> Bottom Shell (爆炸态跨度) */
  for (const [sx, sz] of [[27, 27], [27, -27], [-27, 27], [-27, -27]]) {
    makeDashed(v3(sx, -16.5, sz), v3(sx, 46.5, sz));
  }
  /* 斜向虚线: Shutter / WRITE PROTECT TAB 连到下壳对应位置 */
  makeDashed(v3(-7, -14.5, 29.5), v3(-31, -15, 31));
  makeDashed(v3(26.5, -14.5, -26.5), v3(33, -15, -33));
}

/* ================= 可动部件 (双状态位置 + 透明度目标) ================= */
let parts = [];
function setupParts() {
  const top     = createTopShell();
  const linerU  = createDustLiner();
  const disk    = createMagneticDisk();
  const hub     = createHub();
  const linerL  = createDustLiner();
  const bottom  = createBottomShell();
  const shutter = createShutter();
  const tab     = createWriteProtectTab();

  scene.add(top.group, linerU.group, disk.group, hub.group,
            linerL.group, bottom.group, shutter.group, tab.group);

  parts = [
    /* 名称           assembled -> exploded                     delay  mats 目标opacity */
    { name: 'TOP SHELL',        group: top.group,     from: v3(0, 1.5, 0),    to: v3(0, 45, 0),    delay: 0 * STAGGER_MS, mats: top.fillMats,    target: 0.08 },
    { name: 'DUST LINER (上)',  group: linerU.group,  from: v3(0, 1.0, 0),    to: v3(0, 30, 0),    delay: 1 * STAGGER_MS, mats: linerU.fillMats, target: 0.08 },
    { name: 'MAGNETIC DISK',    group: disk.group,    from: v3(0, 0.5, 0),    to: v3(0, 15, 0),    delay: 2 * STAGGER_MS, mats: disk.fillMats,   target: 0.5 },
    { name: 'HUB',              group: hub.group,     from: v3(0, 0.7, 0),    to: v3(0, 18, 0),    delay: 3 * STAGGER_MS, mats: hub.fillMats,    target: 0.5 },
    { name: 'DUST LINER (下)',  group: linerL.group,  from: v3(0, 0.0, 0),    to: v3(0, 0, 0),     delay: 4 * STAGGER_MS, mats: linerL.fillMats, target: 0.08 },
    { name: 'BOTTOM SHELL',     group: bottom.group,  from: v3(0, -1.5, 0),   to: v3(0, -15, 0),   delay: 5 * STAGGER_MS, mats: bottom.fillMats, target: 0.08 },
    /* SHUTTER: 组装态嵌入下壳前缘 (0,-1.5,22); 爆炸态飞至左前方; 不参与透明度动画 */
    { name: 'SHUTTER',          group: shutter.group, from: v3(0, -1.5, 22),  to: v3(-32, -15, 32), delay: 6 * STAGGER_MS, mats: [], target: 1 },
    { name: 'WRITE PROTECT TAB',group: tab.group,     from: v3(26.5, -1, -26.5), to: v3(34, -15, -34), delay: 7 * STAGGER_MS, mats: tab.fillMats, target: 0.5 },
  ];
  for (const p of parts) {
    p.dur = EXPLODE_DURATION - p.delay; // 所有部件同一时刻到达终点 (~3s)
    for (const m of p.mats) { m.assembled = 1; m.exploded = p.target; }
  }
}

/* ================= 动画状态机 ================= */
/* === ANIMATION: state machine === */
let animState = 'assembled'; // assembled | exploding | exploded | collapsing
let animElapsed = 0;
const tweens = [];

/* 通用补间 (标注/虚线淡入淡出) */
function addTween(obj, key, from, to, dur, delay = 0) {
  tweens.push({ obj, key, from, to, dur, delay, elapsed: 0 });
}
function updateTweens(dt) {
  for (let i = tweens.length - 1; i >= 0; i--) {
    const tw = tweens[i];
    tw.elapsed += dt * 1000;
    const t = clamp((tw.elapsed - tw.delay) / tw.dur, 0, 1);
    tw.obj[tw.key] = lerp(tw.from, tw.to, easeInOutCubic(t));
    if (t >= 1) tweens.splice(i, 1);
  }
}

/* === ANIMATION: explode trigger === */
function triggerExplode() {
  if (animState !== 'assembled') return; // 动画进行中忽略
  animState = 'exploding';
  animElapsed = 0;
  showHint(false);
}
/* === ANIMATION: collapse trigger === */
function triggerCollapse() {
  if (animState !== 'exploded') return;
  hideLabels();                  // 标注/虚线先淡出
  animState = 'collapsing';
  animElapsed = -350;            // 等 ~0.35s 淡出完成再开始收回
}

/* 爆炸完成: 先虚线, 再标签逐条淡入 */
function onExploded() {
  setTimeout(() => {             // +200ms: 虚线
    for (const l of dashedLines) { l.visible = true; addTween(l.material, 'opacity', 0, 1, 600, 0); }
  }, 200);
  setTimeout(showLabels, 400);   // 再 +200ms: 标签 (60ms 错峰, 从上到下)
}
function showLabels() {
  labels.forEach((lbl, i) => {
    setTimeout(() => {
      lbl.div.style.opacity = 1;                     // CSS 过渡自动淡入
      addTween(lbl.leaderMat, 'opacity', 0, 1, 400, 0); // 引线同步
    }, i * 60);
  });
}
function hideLabels() {
  for (const lbl of labels) { lbl.div.style.opacity = 0; lbl.leaderMat.opacity = 0; }
  for (const l of dashedLines) l.material.opacity = 0;
}
function showHint(on) {
  document.getElementById('hint').style.opacity = on ? 1 : 0;
}

/* === ANIMATION: 主推进 (位置 + 透明度同步 lerp) === */
function updateAnimation(dt) {
  updateTweens(dt);
  if (animState !== 'exploding' && animState !== 'collapsing') return;

  const exploding = animState === 'exploding';
  animElapsed += dt * 1000;

  let allDone = true, maxP = 0;
  for (const part of parts) {
    const t = clamp((animElapsed - part.delay) / part.dur, 0, 1);
    const e = easeInOutCubic(t);
    maxP = Math.max(maxP, e);
    if (t < 1) allDone = false;

    /* 位移插值 (Y, 必要时 X/Z) */
    if (exploding) part.group.position.lerpVectors(part.from, part.to, e);
    else part.group.position.lerpVectors(part.to, part.from, e);

    /* 透明度与位移使用同一 progress: 合体端 1 -> 展开端目标值 */
    const op = exploding ? e : 1 - e;
    for (const m of part.mats) m.opacity = lerp(m.assembled, m.exploded, op);
  }

  /* 相机轻微跟随: 目标从 (0,0,0) 漂移到 (0,15,0), 收回时返回 */
  controls.target.y = 15 * (exploding ? maxP : 1 - maxP);
  controls.update();

  if (allDone) {
    if (exploding) { animState = 'exploded'; onExploded(); }
    else           { animState = 'assembled'; showHint(true); }
  }
}

/* === ANIMATION: 空格触发 === */
document.addEventListener('keydown', (e) => {
  if (e.code !== 'Space') return;
  e.preventDefault();
  if (animState === 'assembled') triggerExplode();
