renderer.setPixelRatio(window.devicePixelRatio);
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setClearColor(0x000000, 0); // 透明背景, 露出点阵网格
renderer.domElement.style.zIndex = '1';
container.appendChild(renderer.domElement);

const labelRenderer = new THREE.CSS2DRenderer();
labelRenderer.setSize(window.innerWidth, window.innerHeight);
labelRenderer.domElement.style.zIndex = '2';
container.appendChild(labelRenderer.domElement);

const scene = new THREE.Scene();

/* 正交相机: 等距视角 */
const FRUSTUM = 90;
const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 2000);
camera.position.set(100, 80, 100);
camera.lookAt(0, 0, 0);

/* ================= 点阵网格背景 ================= */
(function initDotGrid() {
  const canvas = document.getElementById('dotgrid');
  const ctx = canvas.getContext('2d');
  function draw() {
    const dpr = window.devicePixelRatio || 1;
    const w = window.innerWidth, h = window.innerHeight;
    canvas.width = w * dpr; canvas.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = '#F5F7FA';
    ctx.fillRect(0, 0, w, h);
    const spacing = 26, r = 1.1;
    ctx.fillStyle = '#c7d4ec';
    for (let x = spacing / 2; x < w; x += spacing) {
      for (let y = spacing / 2; y < h; y += spacing) {
        ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
      }
    }
  }
  draw();
  window.addEventListener('resize', draw);
})();

/* ================= 交互: OrbitControls (必须) ================= */
let controls;
function setupControls() {
  controls = new THREE.OrbitControls(camera, renderer.domElement);
  /* 与 DCC 习惯一致: 左键旋转 / 中键+滚轮缩放 / 右键平移 */
  controls.mouseButtons.LEFT   = THREE.MOUSE.ROTATE;
  controls.mouseButtons.MIDDLE = THREE.MOUSE.DOLLY;
  controls.mouseButtons.RIGHT  = THREE.MOUSE.PAN;
  controls.enableRotate = true;
  controls.enableZoom   = true;   // 滚轮缩放必须可用
  controls.enablePan    = true;
  /* 正交相机: 用 minZoom/maxZoom 限制缩放 */
  controls.minZoom = 0.5;
  controls.maxZoom = 2.5;
  controls.zoom = 1.0;
  controls.target.set(0, 0, 0);
  controls.update();
  /* 平移范围钳制: 限制 target 移动半径, 避免软盘拖出画面过多 */
  controls.addEventListener('change', () => {
    if (controls.target.length() > 70) controls.target.setLength(70);
  });
  /* 阻止右键菜单遮挡平移 */
  renderer.domElement.addEventListener('contextmenu', (e) => e.preventDefault());
}

/* ================= 标注与引线 ================= */
const LABEL_DEFS = [
  { text: 'HD NOTCH',            pos: [-42, 47.5, -33], target: [-28, 46.3, -28] },
  { text: 'TOP SHELL',           pos: [26, 48.5, 22],   target: [10, 46.3, 10] },
  { text: 'DUST LINER (UPPER)',  pos: [-26, 31.5, -16], target: [-10, 30.2, -20] },
  { text: 'HUB',                 pos: [-16, 19.5, 12],  target: [-3, 18.3, 3] },
  { text: 'MAGNETIC DISK',       pos: [24, 16.5, -20],  target: [12, 15.2, -8] },
  { text: 'DUST LINER (LOWER)',  pos: [-24, 1.5, -14],  target: [-10, 0.2, -20] },
  { text: 'BOTTOM SHELL',        pos: [24, -17.5, 20],  target: [10, -14.2, 10] },
  { text: 'LIFTER',              pos: [18, -12.5, 16],  target: [4, -13.2, 9] },
  { text: 'SHUTTER SPRING',      pos: [18, -12, 30],    target: [2, -14.8, 29.5] },
  { text: 'WRITE PROTECT NOTCH', pos: [38, -12.5, -22], target: [26.5, -14.2, -26.5] },
  { text: 'SHUTTER',             pos: [-46, -14, 38],   target: [-31, -14.8, 33] },
  { text: 'WRITE PROTECT TAB',   pos: [44, -13.5, -38], target: [33, -14.8, -33] },
];
let labels = [];

function setupLabels() {
  labels = LABEL_DEFS.map((def) => {
    const div = document.createElement('div');
    div.className = 'label';
    div.textContent = def.text;
    div.style.opacity = 0; // 初始隐藏, CSS transition 淡入
    const obj = new THREE.CSS2DObject(div);
    obj.position.set(def.pos[0], def.pos[1], def.pos[2]);
    scene.add(obj);

    /* 每条标注配一条短引线 */
    const leaderMat = lineMat(BLUE, 0);
    const leaderGeo = new THREE.BufferGeometry().setFromPoints([
      v3(def.pos[0], def.pos[1], def.pos[2]),
      v3(def.target[0], def.target[1], def.target[2]),
    ]);
    const leader = new THREE.Line(leaderGeo, leaderMat);
    leader.renderOrder = 11;
    scene.add(leader);

    return { div, leaderMat, anchorY: def.pos[1] };
  });
  /* 淡入顺序: 从上到下 */
  labels.sort((a, b) => b.anchorY - a.anchorY);
}

/* ================= 连接虚线 (LineDashedMaterial) ================= */
const dashedMat = new THREE.LineDashedMaterial({
  color: BLUE, dashSize: 3, gapSize: 2.5,
  transparent: true, opacity: 0, depthWrite: false,
});
const dashedLines = [];

function makeDashed(a, b) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), dashedMat);
  line.computeLineDistances(); // LineDashedMaterial 必须
  line.renderOrder = 11;
  line.visible = false;
  scene.add(line);
  dashedLines.push(line);
}
function setupDashedLines() {
  /* 4 条垂直虚线: 贯穿四个切角, Top Shell -> Bottom Shell (爆炸态跨度) */
  for (const [sx, sz] of [[27, 27], [27, -27], [-27, 27], [-27, -27]]) {
    makeDashed(v3(sx, -16.5, sz), v3(sx, 46.5, sz));
  }
  /* 斜向虚线: Shutter / WRITE PROTECT TAB 连到下壳对应位置 */
  makeDashed(v3(-7, -14.5, 29.5), v3(-31, -15, 31));
  makeDashed(v3(26.5, -14.5, -26.5), v3(33, -15, -33));
}

/* ================= 可动部件 (双状态位置 + 透明度目标) ================= */
let parts = [];
function setupParts() {
  const top     = createTopShell();
  const linerU  = createDustLiner();
  const disk    = createMagneticDisk();
  const hub     = createHub();
  const linerL  = createDustLiner();
  const bottom  = createBottomShell();
  const shutter = createShutter();
  const tab     = createWriteProtectTab();

  scene.add(top.group, linerU.group, disk.group, hub.group,
            linerL.group, bottom.group, shutter.group, tab.group);

  parts = [
    /* 名称           assembled -> exploded                     delay  mats 目标opacity */
    { name: 'TOP SHELL',        group: top.group,     from: v3(0, 1.5, 0),    to: v3(0, 45, 0),    delay: 0 * STAGGER_MS, mats: top.fillMats,    target: 0.08 },
    { name: 'DUST LINER (上)',  group: linerU.group,  from: v3(0, 1.0, 0),    to: v3(0, 30, 0),    delay: 1 * STAGGER_MS, mats: linerU.fillMats, target: 0.08 },
    { name: 'MAGNETIC DISK',    group: disk.group,    from: v3(0, 0.5, 0),    to: v3(0, 15, 0),    delay: 2 * STAGGER_MS, mats: disk.fillMats,   target: 0.5 },
    { name: 'HUB',              group: hub.group,     from: v3(0, 0.7, 0),    to: v3(0, 18, 0),    delay: 3 * STAGGER_MS, mats: hub.fillMats,    target: 0.5 },
    { name: 'DUST LINER (下)',  group: linerL.group,  from: v3(0, 0.0, 0),    to: v3(0, 0, 0),     delay: 4 * STAGGER_MS, mats: linerL.fillMats, target: 0.08 },
    { name: 'BOTTOM SHELL',     group: bottom.group,  from: v3(0, -1.5, 0),   to: v3(0, -15, 0),   delay: 5 * STAGGER_MS, mats: bottom.fillMats, target: 0.08 },
    /* SHUTTER: 组装态嵌入下壳前缘 (0,-1.5,22); 爆炸态飞至左前方; 不参与透明度动画 */
    { name: 'SHUTTER',          group: shutter.group, from: v3(0, -1.5, 22),  to: v3(-32, -15, 32), delay: 6 * STAGGER_MS, mats: [], target: 1 },
    { name: 'WRITE PROTECT TAB',group: tab.group,     from: v3(26.5, -1, -26.5), to: v3(34, -15, -34), delay: 7 * STAGGER_MS, mats: tab.fillMats, target: 0.5 },
  ];
  for (const p of parts) {
    p.dur = EXPLODE_DURATION - p.delay; // 所有部件同一时刻到达终点 (~3s)
    for (const m of p.mats) { m.assembled = 1; m.exploded = p.target; }
  }
}

/* ================= 动画状态机 ================= */
/* === ANIMATION: state machine === */
let animState = 'assembled'; // assembled | exploding | exploded | collapsing
let animElapsed = 0;
const tweens = [];

/* 通用补间 (标注/虚线淡入淡出) */
function addTween(obj, key, from, to, dur, delay = 0) {
  tweens.push({ obj, key, from, to, dur, delay, elapsed: 0 });
}
function updateTweens(dt) {
  for (let i = tweens.length - 1; i >= 0; i--) {
    const tw = tweens[i];
    tw.elapsed += dt * 1000;
    const t = clamp((tw.elapsed - tw.delay) / tw.dur, 0, 1);
    tw.obj[tw.key] = lerp(tw.from, tw.to, easeInOutCubic(t));
    if (t >= 1) tweens.splice(i, 1);
  }
}

/* === ANIMATION: explode trigger === */
function triggerExplode() {
  if (animState !== 'assembled') return; // 动画进行中忽略
  animState = 'exploding';
  animElapsed = 0;
  showHint(false);
}
/* === ANIMATION: collapse trigger === */
function triggerCollapse() {
  if (animState !== 'exploded') return;
  hideLabels();                  // 标注/虚线先淡出
  animState = 'collapsing';
  animElapsed = -350;            // 等 ~0.35s 淡出完成再开始收回
}

/* 爆炸完成: 先虚线, 再标签逐条淡入 */
function onExploded() {
  setTimeout(() => {             // +200ms: 虚线
    for (const l of dashedLines) { l.visible = true; addTween(l.material, 'opacity', 0, 1, 600, 0); }
  }, 200);
  setTimeout(showLabels, 400);   // 再 +200ms: 标签 (60ms 错峰, 从上到下)
}
function showLabels() {
  labels.forEach((lbl, i) => {
    setTimeout(() => {
      lbl.div.style.opacity = 1;                     // CSS 过渡自动淡入
      addTween(lbl.leaderMat, 'opacity', 0, 1, 400, 0); // 引线同步
    }, i * 60);
  });
}
function hideLabels() {
  for (const lbl of labels) { lbl.div.style.opacity = 0; lbl.leaderMat.opacity = 0; }
  for (const l of dashedLines) l.material.opacity = 0;
}
function showHint(on) {
  document.getElementById('hint').style.opacity = on ? 1 : 0;
}

/* === ANIMATION: 主推进 (位置 + 透明度同步 lerp) === */
function updateAnimation(dt) {
  updateTweens(dt);
  if (animState !== 'exploding' && animState !== 'collapsing') return;

  const exploding = animState === 'exploding';
  animElapsed += dt * 1000;

  let allDone = true, maxP = 0;
  for (const part of parts) {
    const t = clamp((animElapsed - part.delay) / part.dur, 0, 1);
    const e = easeInOutCubic(t);
    maxP = Math.max(maxP, e);
    if (t < 1) allDone = false;

    /* 位移插值 (Y, 必要时 X/Z) */
    if (exploding) part.group.position.lerpVectors(part.from, part.to, e);
    else part.group.position.lerpVectors(part.to, part.from, e);

    /* 透明度与位移使用同一 progress: 合体端 1 -> 展开端目标值 */
    const op = exploding ? e : 1 - e;
    for (const m of part.mats) m.opacity = lerp(m.assembled, m.exploded, op);
  }

  /* 相机轻微跟随: 目标从 (0,0,0) 漂移到 (0,15,0), 收回时返回 */
  controls.target.y = 15 * (exploding ? maxP : 1 - maxP);
  controls.update();

  if (allDone) {
    if (exploding) { animState = 'exploded'; onExploded(); }
    else           { animState = 'assembled'; showHint(true); }
  }
}

/* === ANIMATION: 空格触发 === */
document.addEventListener('keydown', (e) => {
  if (e.code !== 'Space') return;
  e.preventDefault();
  if (animState === 'assembled') triggerExplode();
  else if (animState === 'exploded') triggerCollapse();
  /* exploding / collapsing 期间忽略 */
});

/* ================= 窗口尺寸 ================= */
function onResize() {
  const w = window.innerWidth, h = window.innerHeight;
  const aspect = w / h;
  camera.left = -FRUSTUM * aspect / 2;
  camera.right = FRUSTUM * aspect / 2;
  camera.top = FRUSTUM / 2;
  camera.bottom = -FRUSTUM / 2;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  labelRenderer.setSize(w, h);
}
window.addEventListener('resize', onResize);
onResize();

/* ================= 主循环 ================= */
const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  updateAnimation(clock.getDelta());
  controls.update();
  renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
}

setupParts();
setupLabels();
setupDashedLines();
setupControls();
animate();

/* ============================================================================
 * ── 快门与开孔自检 (逐条确认) ─────────────────────────────────────────────
 *  1. SHUTTER 本体为不透明金属感:
 *     MeshBasicMaterial({ color: 0x4a5568 }) — transparent=false, 非半透明幽灵面;
 *     createShutter() 中 fillMats 为空数组, 不参与任何透明度 lerp;
 *     爆炸态仍保持不透明, 仅随 Group 位移到 (-32,-15,32)。
 *  2. SHUTTER 矩形真镂空, 偏左, 开孔短边与快门长边平行:
 *     板面 22(X)x16(Z), 窗口 X∈[-10,-4] (组中心 x=0, 明显偏左);
 *     窗口短边 6 沿 X (∥ 快门长边 22), 窗口长边 14 沿 Z (∥ 快门短边 16),
 *     即开孔长轴 ⟂ 快门长轴; 由 Shape + holes + ExtrudeGeometry 实现真镂空。
 *  3. 三处开孔同一套尺寸与局部坐标, 组装态对齐:
 *     HEAD_CHANNEL = { x:-10, w:6, z:15, h:14 } 被 3.1(d)、3.6(g)、3.7 共用;
 *     上壳/下壳孔洞: X∈[-10,-4], Z∈[15,29]; 快门组组装于 (0,-1.5,22),
 *     窗口局部 Z∈[-7,7] -> 世界 Z∈[15,29], 三处 XZ 足迹完全重合 (同一磁头通道)。
 * ========================================================================== */
</script>
</body>
</html>
"}

